        // håret över örat hör till sidhåret: det döljs bara när huvudbonaden täcker sidorna, så att inga lösa testar blir kvar (Björn: ja)
        if (b.har && z === 'oron') z = 'sidor';
        if (z && b.maskbar && masker.has(z)) continue;
