    const rock = p.klader.rock, farg = z => (rock && (z === 'bal' || z === 'armar')) ? rock : (p.klader.skjorta && (z === 'bal' || z === 'armar')) ? 'lin' : (z === 'ben' && p.klader.byxor) ? p.klader.byxor : (z === 'fotter' && p.klader.skor ? 'harskinn' : 'hud');
